namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals and salads", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and baking", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites and appetizers", Icon = "🧀" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Fluffy Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
                Steps = "1. Mix dry ingredients\n2. Whisk eggs and milk together\n3. Combine wet and dry ingredients\n4. Cook on griddle until bubbles form\n5. Flip and cook until golden",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop lettuce\n2. Toss with dressing\n3. Add croutons and parmesan\n4. Top with grilled chicken if desired",
                AverageRating = 4.0, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner",
                Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n100g pecorino romano\nBlack pepper",
                Steps = "1. Cook pasta in salted water\n2. Fry pancetta until crispy\n3. Mix egg yolks with cheese and pepper\n4. Toss hot pasta with pancetta\n5. Remove from heat, stir in egg mixture\n6. Serve immediately",
                AverageRating = 4.8, RatingCount = 25
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n100g butter\n3 eggs\n100g sugar\n50g flour",
                Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold in chocolate mixture and flour\n4. Pour into greased ramekins\n5. Bake at 200°C for 12 minutes\n6. Invert onto plate and serve",
                AverageRating = 4.9, RatingCount = 30
            },
            new()
            {
                Id = 5, Title = "Bruschetta", Category = "Snacks",
                Ingredients = "1 baguette\n4 tomatoes\nFresh basil\n2 cloves garlic\nOlive oil\nBalsamic vinegar",
                Steps = "1. Slice and toast baguette\n2. Dice tomatoes and mix with chopped basil\n3. Add minced garlic and olive oil\n4. Spoon mixture onto toast\n5. Drizzle with balsamic vinegar",
                AverageRating = 4.2, RatingCount = 15
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
    }
}

